#if NET10_0_OR_GREATER
namespace EngineeringUnits;

/// <summary>For the implicit conversions to EngineeringUnits.Fast in FastConversions.g.cs (generated by CodeGen.Fast).</summary>
internal static class FastConversion
{
    /// <summary>
    /// The SI value of a quantity, exactly as it holds it. Not <c>As(XUnit.SI)</c>: that goes through decimal, which keeps only
    /// 28 decimal places - 1 µg/day loses digits and 1e-30 m (from arithmetic) becomes 0.
    /// </summary>
    public static double SI(BaseUnit value, UnitTypebase siUnit) =>
        value.Unit.IsSIUnit()
            ? BaseUnitExtensions.As(value, value.Unit)                          // already SI: the stored value itself, bit for bit
            : BaseUnitExtensions.GetValueAs(value, siUnit.Unit).ToDouble();     // exact Fraction conversion, rounded once
}
#endif
